from hermes_tools import terminal
cmd = "python3 - <<'PY'
H,W=28,12
pts={(25,8):2,(26,6):0,(26,7):2,(27,6):2,(27,7):0}
lines={'0':[(26,6),(27,7)],'2':[(25,8),(26,7),(27,6)]}
for color, coords in lines.items():
    (r0,c0),(r1,c1)=coords[:2]
    dr=(r1-r0)//abs(r1-r0); dc=(c1-c0)//abs(c1-c0)
    # endpoint extension directions
    for r,c,drs,dcs in [(coords[0][0],coords[0][1],-dr,-dc),(coords[-1][0],coords[-1][1],dr,dc)]:
        rr,cc=r+drs,c+dcs; ray=[]
        while 0<=rr<H and 0<=cc<W and (rr,cc) not in pts:
            ray.append((rr,cc)); rr+=drs; cc+=dcs
        print(color, 'ray:',ray, 'stops at', (rr,cc), 'occupied=',pts.get((rr,cc)))
PY"
print(terminal(cmd))

